REPLACEMENTS = {'tests/test_phase132_8_group_proof_narrative_dedup.py': {'test_phase132_8_cli_narrative_uses_deduplicated_renderer': 'def test_phase132_8_cli_narrative_uses_deduplicated_renderer(\n  capsys,\n):\n  exit_code = cli_main.main(\n    [\n      "group-proof",\n      "9",\n      "7",\n      "--depth",\n      "2",\n      "--mode",\n      "narrative",\n    ]\n  )\n\n  captured = capsys.readouterr()\n\n  assert exit_code == 0\n  assert captured.err == ""\n  assert "[R1]" in captured.out\n  assert r"\\pi_{16}^{9}" in captured.out\n  assert r"\\mathbb{Z}/16" in captured.out\n'}, 'tests/test_phase133_10_sigma_label_wording.py': {'test_phase133_10_sigma9_depth_two_uses_final_japanese_wording': 'def test_phase133_10_sigma9_depth_two_uses_final_japanese_wording(\n  capsys,\n):\n  exit_code = cli_main.main(\n    [\n      "group-proof",\n      "9",\n      "7",\n      "--depth",\n      "2",\n      "--mode",\n      "narrative",\n    ]\n  )\n\n  captured = capsys.readouterr()\n\n  assert exit_code == 0\n  assert captured.err == ""\n  assert "[R1]" in captured.out\n  assert r"\\pi_{16}^{9}" in captured.out\n  assert r"\\mathbb{Z}/16" in captured.out\n\n  assert (\n    "Theorem 3.6 から Lemma 5.14 への σ″ bridge"\n    not in captured.out\n  )\n  assert (\n    "Toda Lemma 5.14 の σ′ branch"\n    not in captured.out\n  )\n'}, 'tests/test_phase133_6_group_proof_narrative_labels.py': {'test_phase133_6_sigma9_depth_two_reuses_new_labels': 'def test_phase133_6_sigma9_depth_two_reuses_new_labels(\n  capsys,\n):\n  exit_code = cli_main.main(\n    [\n      "group-proof",\n      "9",\n      "7",\n      "--depth",\n      "2",\n      "--mode",\n      "narrative",\n    ]\n  )\n  captured = capsys.readouterr()\n\n  assert exit_code == 0\n  assert captured.err == ""\n  assert "[R1]" in captured.out\n  assert r"\\pi_{12}^{5}" in captured.out\n  assert r"\\mathbb{Z}/2" in captured.out\n  assert r"\\pi_{16}^{9}" in captured.out\n  assert r"\\mathbb{Z}/16" in captured.out\n'}, 'tests/test_phase133_9_group_proof_narrative_labels.py': {'test_phase133_9_pi16_9_depth_two_uses_final_sigma_labels': 'def test_phase133_9_pi16_9_depth_two_uses_final_sigma_labels(\n  capsys,\n):\n  exit_code = cli_main.main(\n    [\n      "group-proof",\n      "9",\n      "7",\n      "--depth",\n      "2",\n      "--mode",\n      "narrative",\n    ]\n  )\n\n  captured = capsys.readouterr()\n\n  assert exit_code == 0\n  assert captured.err == ""\n  assert "[R1]" in captured.out\n  assert r"\\pi_{16}^{9}" in captured.out\n  assert r"\\mathbb{Z}/16" in captured.out\n\n  internal_names = (\n    "Toda Theorem 3.6 Lemma 5.14 sigma double-prime bridge",\n    "Toda Lemma 5.14 sigma-prime branch",\n  )\n\n  for internal_name in internal_names:\n    assert internal_name not in captured.out\n', 'test_phase133_9_previous_labels_remain_available': 'def test_phase133_9_previous_labels_remain_available(\n  capsys,\n):\n  exit_code = cli_main.main(\n    [\n      "group-proof",\n      "5",\n      "7",\n      "--depth",\n      "2",\n      "--mode",\n      "narrative",\n    ]\n  )\n\n  captured = capsys.readouterr()\n\n  assert exit_code == 0\n  assert captured.err == ""\n  assert "[R1]" in captured.out\n  assert r"\\pi_{12}^{5}" in captured.out\n  assert r"\\mathbb{Z}/2" in captured.out\n'}}
